using System.Collections; using UnityEngine; using UnityEngine.UI;
namespace Reflectable { public sealed class ReflectableBlockView:MonoBehaviour { [SerializeField] Text hpLabel; Transform visual; public int Row{get;set;} public int Column{get;set;} public int HP{get;private set;} public int MaxHP{get;private set;} public ReflectableBlockType Type{get;private set;} void Awake(){visual=transform.Find("Visual")??transform;} public void Setup(ReflectableGameController owner,int row,int col,int hp,int max,ReflectableBlockType type){Row=row;Column=col;HP=hp;MaxHP=max;Type=type;Refresh();StartCoroutine(SpawnIn());} public void ApplyDamage(int amount){HP-=amount;Refresh();StartCoroutine(Punch());} void Refresh(){if(hpLabel)hpLabel.text=HP.ToString();} IEnumerator SpawnIn(){var target=transform.position;transform.position=target+Vector3.up*.45f;visual.localScale=Vector3.one*.86f;for(float t=0;t<.22f;t+=Time.deltaTime){float p=1f-Mathf.Pow(1f-t/.22f,3f);transform.position=Vector3.Lerp(target+Vector3.up*.45f,target,p);visual.localScale=Vector3.Lerp(Vector3.one*.86f,Vector3.one,p);yield return null;}if(this){transform.position=target;visual.localScale=Vector3.one;}} IEnumerator Punch(){var s=visual.localScale;for(float t=0;t<.06f;t+=Time.deltaTime){visual.localScale=Vector3.Lerp(s,s*1.10f,t/.06f);yield return null;}for(float t=0;t<.08f;t+=Time.deltaTime){visual.localScale=Vector3.Lerp(s*1.10f,s,t/.08f);yield return null;}if(this)visual.localScale=s;} public IEnumerator MoveTo(Vector2 target,float duration){var start=(Vector2)transform.position;for(float t=0;t<duration;t+=Time.deltaTime){transform.position=Vector2.Lerp(start,target,Mathf.SmoothStep(0,1,t/duration));yield return null;}if(this)transform.position=target;} } }
